// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import java.lang.reflect.Method;

import org.eclipse.rdf4j.query.QueryEvaluationException;
import org.eclipse.rdf4j.query.QueryInterruptedException;
import org.junit.jupiter.api.Test;

/** Terminal interruption must not become an optimizer decline before kernel execution starts. */
class LmdbNativeKernelInterruptionClassificationTest {

	@Test
	void directInterruptionIsTerminalBeforeExecution() throws Exception {
		QueryInterruptedException problem = new QueryInterruptedException("owned record cancelled");
		assertThat(terminal(problem)).isSameAs(problem);
	}

	@Test
	void wrappedInterruptionPreservesWrapperAndCleanupFailure() throws Exception {
		QueryInterruptedException interruption = new QueryInterruptedException("lifecycle cancelled");
		QueryEvaluationException problem = new QueryEvaluationException(interruption);
		IllegalStateException cleanup = new IllegalStateException("cleanup failed");
		problem.addSuppressed(cleanup);
		assertThat(terminal(problem)).isSameAs(problem);
		assertThat(problem.getSuppressed()).containsExactly(cleanup);
	}

	@Test
	void ordinaryPreExecutionFailureRetainsExistingDeclineClassification() throws Exception {
		assertThat(terminal(new IllegalArgumentException("unsupported bind"))).isNull();
	}

	@Test
	void nativeQueryCancellationRetainsOriginalProvenance() throws Exception {
		NativeCancellationToken token = new NativeCancellationToken();
		token.requestCancellation();
		Throwable problem = token.pollCancellation();
		assertThat(terminal(problem)).isSameAs(problem);
	}

	@Test
	void probeDeadlineRetainsTerminalClassification() throws Exception {
		assertThat(terminal(LmdbNativeProbeDeadlineExceeded.INSTANCE))
				.isSameAs(LmdbNativeProbeDeadlineExceeded.INSTANCE);
	}

	private static Throwable terminal(Throwable problem) throws Exception {
		Method method = LmdbNativeKernelExecution.class.getDeclaredMethod("serialTerminalFailure", Throwable.class);
		method.setAccessible(true);
		return (Throwable) method.invoke(null, problem);
	}
}
